@dataclasses.dataclass
class DataScanConfig:
    # The data source for DataScan.
    data: Any = None
    # The output of a data discovery scan.
    data_discovery_result: Any = None
    # Spec for a data discovery scan.
    data_discovery_spec: Any = None
    # The output of a DataDocumentation scan.
    data_documentation_result: Any = None
    # DataDocumentation scan related spec.
    data_documentation_spec: Any = None
    # DataProfileResult defines the output of DataProfileScan. Each field of the table will have field type specific profile result.
    data_profile_result: Any = None
    # DataProfileScan related setting.
    data_profile_spec: Any = None
    # The output of a DataQualityScan.
    data_quality_result: Any = None
    # DataQualityScan related setting.
    data_quality_spec: Any = None
    # Optional. Description of the scan. Must be between 1-1024 characters.
    description: Any = None
    # Optional. User friendly display name. Must be between 1-256 characters.
    display_name: Any = None
    # The identity to run the datascan.
    execution_identity: Any = None
    # DataScan execution settings.
    execution_spec: Any = None
    # Status of the data scan execution.
    execution_status: Any = None
    # Optional. User-defined labels for the scan.
    labels: Any = None
    # Contains the result of an unstructured data profile scan.
    unstructured_data_profile_result: Any = None
    # Contains the specification for an unstructured data profile scan.
    unstructured_data_profile_spec: Any = None

